const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Antarctic region (south of 60°S)
  const antarcticRegion = ee.Geometry.Rectangle([-180, -90, 180, -60]);

  // Load Sentinel-5P Ozone data
  const o3Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
    .filterBounds(antarcticRegion);

  // January 1, 2021
  const jan1_2021 = o3Collection
    .filterDate('2021-01-01', '2021-01-02')
    .first();

  // October 7, 2021
  const oct7_2021 = o3Collection
    .filterDate('2021-10-07', '2021-10-08')
    .first();

  // Check if images exist
  const jan1_exists = jan1_2021.bandNames().size().getInfo() > 0;
  const oct7_exists = oct7_2021.bandNames().size().getInfo() > 0;

  if (!jan1_exists || !oct7_exists) {
    print("Missing data for one or both dates.");
    print("<answer>C1</answer>");
    return;
  }

  // Extract O3 column band (in DU)
  const jan1_o3 = jan1_2021.select('O3_column_number_density');
  const oct7_o3 = oct7_2021.select('O3_column_number_density');

  // Validate data values
  const jan1_mean = jan1_o3.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: antarcticRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  const oct7_mean = oct7_o3.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: antarcticRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  if (jan1_mean === null || oct7_mean === null || isNaN(jan1_mean) || isNaN(oct7_mean)) {
    print("Invalid O3 values detected.");
    print("<answer>C3</answer>");
    return;
  }

  // Define ozone hole as O3 column < 220 DU
  const ozoneHoleThreshold = 220;

  // Calculate ozone hole area (count pixels < 220 DU)
  const jan1_hole = jan1_o3.lt(ozoneHoleThreshold);
  const oct7_hole = oct7_o3.lt(ozoneHoleThreshold);

  const jan1_count = jan1_hole.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: antarcticRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  const oct7_count = oct7_hole.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: antarcticRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  // Calculate ozone hole pixel area (number of pixels with O3 < 220 DU)
  const jan1_holeArea = jan1_hole.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarcticRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  const oct7_holeArea = oct7_hole.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarcticRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('O3_column_number_density').getInfo();

  // Validate results
  if (jan1_holeArea === null || oct7_holeArea === null) {
    print("Ozone hole area calculation failed.");
    print("<answer>C3</answer>");
    return;
  }

  print("Jan 1, 2021 - O3 Mean: " + (jan1_mean / 46.698).toFixed(1) + " DU, Hole Pixels: " + jan1_holeArea);
  print("Oct 7, 2021 - O3 Mean: " + (oct7_mean / 46.698).toFixed(1) + " DU, Hole Pixels: " + oct7_holeArea);

  // Compare ozone hole areas
  if (oct7_holeArea > jan1_holeArea) {
    print("Oct 7, 2021 ozone hole was larger than Jan 1, 2021.");
    print("<answer>A</answer>");
  } else {
    print("Oct 7, 2021 ozone hole was not larger than Jan 1, 2021.");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
